  "types": "./types/index.d.ts",
  "keywords": [
    "claude-code",
    "claude-mod",
    "agent",
    "assistant",
    "scheduled",
    "dracula"
  ],
  "userConfig": {
    "workEveryMinutes": {
      "type": "number",
      "title": "Work round interval (minutes)",
      "description": "How often a background round runs. A round with no queued goal stops right away.",
      "default": 30
    },
    "briefingTime": {
      "type": "string",
